import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import clihelp  # noqa: E402

COLS = ["region", "prod", "amt"]
ROWS = [["n", "a", "1"], ["s", "b", "2.5"], ["n", "b", "3"], ["n", "a", "4"], ["e", "c", "0.5"]]
FILES = {"t.csv": clihelp.csv_text(COLS, ROWS)}


class PivotTests(clihelp.CliCase):
    def test_sums_by_row_and_column_in_first_appearance_order(self):
        self.check_ok(["pivot", "t.csv", "region", "prod", "amt"], ["region", "a", "b", "c"],
                      [["n", "5", "3", "0"], ["s", "0", "2.5", "0"], ["e", "0", "0", "0.5"]], files=FILES)

    def test_the_other_way_round(self):
        self.check_ok(["pivot", "t.csv", "prod", "region", "amt"], ["prod", "n", "s", "e"],
                      [["a", "5", "0", "0"], ["b", "3", "2.5", "0"], ["c", "0", "0", "0.5"]], files=FILES)

    def test_sums_are_exact_decimals_and_keep_their_digits(self):
        files = {"t.csv": "r,c,v\nx,k,0.1\nx,k,0.2\ny,k,1.50\ny,k,0.5\nz,k,-1\nz,k,1\nw,k, +2 \n"}
        self.check_ok(["pivot", "t.csv", "r", "c", "v"], ["r", "k"],
                      [["x", "0.3"], ["y", "2.00"], ["z", "0"], ["w", "2"]], files=files)

    def test_row_and_column_values_match_as_exact_text(self):
        files = {"t.csv": "r,c,v\nx,a,1\nX,a,2\nx,A,4\nx, a,8\nx,a,16\n"}
        self.check_ok(["pivot", "t.csv", "r", "c", "v"], ["r", "a", "A", " a"],
                      [["x", "17", "4", "8"], ["X", "2", "0", "0"]], files=files)

    def test_an_empty_row_value_is_a_row(self):
        files = {"t.csv": "r,c,v\n,a,1\nx,a,2\n,b,3\n"}
        self.check_ok(["pivot", "t.csv", "r", "c", "v"], ["r", "a", "b"], [["", "1", "3"], ["x", "2", "0"]],
                      files=files)

    def test_the_value_column_may_be_the_row_or_column_column(self):
        files = {"t.csv": "k,n\na,1\na,2\nb,1\n"}
        self.check_ok(["pivot", "t.csv", "k", "n", "n"], ["k", "1", "2"], [["a", "1", "2"], ["b", "1", "0"]],
                      files=files)

    def test_no_rows_gives_only_the_row_column(self):
        self.check_ok(["pivot", "t.csv", "r", "c", "v"], ["r"], [], files={"t.csv": "r,c,v\n"})

    def test_a_column_value_may_equal_another_columns_name_of_the_file(self):
        files = {"t.csv": "r,c,v\nx,v,1\nx,c,2\n"}
        self.check_ok(["pivot", "t.csv", "r", "c", "v"], ["r", "v", "c"], [["x", "1", "2"]], files=files)

    def test_row_and_column_must_differ(self):
        self.check_fail([["pivot", "t.csv", "prod", "prod", "amt"], ["pivot", "missing.csv", "x", "x", "y"]], 2,
                        files=FILES)

    def test_exactly_four_arguments(self):
        self.check_fail([["pivot"], ["pivot", "t.csv"], ["pivot", "t.csv", "region"],
                         ["pivot", "t.csv", "region", "prod"],
                         ["pivot", "t.csv", "region", "prod", "amt", "extra"]], 2, files=FILES)

    def test_empty_column_value_names_the_file_row(self):
        self.check_fail([["pivot", "t.csv", "r", "c", "v"]], 1, files={"t.csv": "r,c,v\nx,a,1\nx,,2\ny,b,3\n"},
                        message="t.csv: row 2: column 'c': empty value")

    def test_column_value_equal_to_the_row_columns_name_names_the_file_row(self):
        self.check_fail([["pivot", "t.csv", "r", "c", "v"]], 1, files={"t.csv": "r,c,v\nx,a,1\nx,b,2\ny,r,3\n"},
                        message="t.csv: row 3: column 'c': value 'r' is the name of the row column")

    def test_non_number_value_names_the_file_row(self):
        self.check_fail([["pivot", "t.csv", "r", "c", "v"]], 1, files={"t.csv": "r,c,v\nx,a,1\ny,b,oops\n"},
                        message="t.csv: row 2: column 'v': 'oops' is not a number")
        self.check_fail([["pivot", "t.csv", "r", "c", "v"]], 1, files={"t.csv": "r,c,v\nx,a,\n"},
                        message="t.csv: row 1: column 'v'")

    def test_the_first_problem_in_file_order_wins_and_an_empty_column_value_beats_a_bad_number(self):
        self.check_fail([["pivot", "t.csv", "r", "c", "v"]], 1, files={"t.csv": "r,c,v\nx,,oops\ny,b,oops\n"},
                        message="row 1: column 'c': empty value")
        self.check_fail([["pivot", "t.csv", "r", "c", "v"]], 1, files={"t.csv": "r,c,v\nx,r,oops\n"},
                        message="row 1: column 'c': value 'r' is the name of the row column")
        self.check_fail([["pivot", "t.csv", "r", "c", "v"]], 1, files={"t.csv": "r,c,v\nx,a,oops\ny,,1\n"},
                        message="row 1: column 'v': 'oops' is not a number")

    def test_unknown_columns_and_missing_file(self):
        self.check_fail([["pivot", "t.csv", "nope", "prod", "amt"], ["pivot", "t.csv", "region", "nope", "amt"],
                         ["pivot", "t.csv", "region", "prod", "nope"]], 1, files=FILES, message="nope")
        self.check_fail([["pivot", "missing.csv", "a", "b", "c"]], 1, files=FILES, message="missing.csv")

    def test_ragged_row_is_a_file_error(self):
        self.check_fail([["pivot", "t.csv", "a", "b", "c"]], 1, files={"t.csv": "a,b,c\n1,2\n"},
                        message="t.csv: line 2")


if __name__ == "__main__":
    unittest.main()
